Extender dm4_stock_restrict_validate con un create() que:
 @api.model
def create(self, vals):
 restrict_group = self.env.ref(
 "dm4_stock_restrict_validate.group_validate_internal_transfer_only"
 )
 if restrict_group in self.env.user.groups_id:
 picking_type = self.env['stock.picking.type'].browse(
 vals.get('picking_type_id')
 )
 if picking_type and picking_type.code in ('incoming', 'outgoing'):
 raise UserError(_(
 "No tenés permiso para crear recepciones ni entregas. "
 "Solo podés crear traslados internos."
 ))
 return super().create(vals)

